mapper.sql:
WHERE a.tenant_uid = #{tenantUid}



        AND (
            a.institution_uid IN

                #{item}


                OR a.hospital_uid = #{hospitalUid}


                OR a.site_uid = #{siteUid}

        )



            AND a.hospital_uid IN

                #{item}



            AND a.hospital_uid = #{hospitalUid}





    AND ap.application_year = #{applicationYear}


    AND ap.application_no LIKE concat('%', #{applicationNo}, '%')


    AND ap.application_type = #{applicationType}


    AND ai.name LIKE concat('%', #{assetName}, '%')


    AND ai.function_type LIKE concat('%', #{functionType}, '%')


    AND h.name LIKE concat('%', #{hospitalName}, '%')


    AND ai.clinical_dept_name LIKE concat('%', #{clinicalDeptName}, '%')


    AND ai.serial_num LIKE concat('%', #{serialNum}, '%')


    AND ai.qr_code LIKE concat('%', #{qrCode}, '%')


    AND ai.install_date >= #{installDateGTE}


    AND ai.install_date <= #{installDateLTE}



    AND EXISTS (SELECT 1 FROM his_equipment_data_result hedr WHERE hedr.asset_uid = a.asset_uid AND hedr.tenant_uid = #{tenantUid})


    AND NOT EXISTS (SELECT 1 FROM his_equipment_data_result hedr WHERE hedr.asset_uid = a.asset_uid AND hedr.tenant_uid = #{tenantUid})
